import 'dart:convert';

import 'package:flutter/material.dart';
import 'package:screen_brightness/screen_brightness.dart';

import '../../api/api_client.dart';
import '../../api/models.dart';
import '../../theme.dart';
import '../../utils/format.dart';
import '../../widgets/common.dart';
import 'event_detail_screen.dart';

/// UC06 - Ticket QR, full screen (design: mobile-10).
///
/// The QR image is generated by the server from the AES-256 encrypted payload
/// {ticket, event, nonce} (BR-07). The phone only displays it, so it can't be
/// forged. Screen brightness is raised so door scanners read it easily.
/// With several tickets of one order, the attendee swipes between them.
class TicketQrScreen extends StatefulWidget {
  final int ticketId;
  final List<int>? groupIds;
  const TicketQrScreen({super.key, required this.ticketId, this.groupIds});

  @override
  State<TicketQrScreen> createState() => _TicketQrScreenState();
}

class _TicketQrScreenState extends State<TicketQrScreen> {
  late final List<int> _ids = widget.groupIds ?? [widget.ticketId];
  late final PageController _pages = PageController(initialPage: _ids.indexOf(widget.ticketId).clamp(0, _ids.length - 1));
  late int _page = _pages.initialPage;

  @override
  void initState() {
    super.initState();
    // Full brightness while the QR is showing; restored when the screen closes
    ScreenBrightness.instance.setApplicationScreenBrightness(1.0).catchError((_) {});
  }

  @override
  void dispose() {
    ScreenBrightness.instance.resetApplicationScreenBrightness().catchError((_) {});
    _pages.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: C.ink,
      body: SafeArea(
        child: Column(
          children: [
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 10, 16, 0),
              child: Row(
                children: [
                  CircleIconButton(icon: Icons.close, tooltip: 'Close', bg: C.dark2, fg: C.bg, onPressed: () => Navigator.of(context).pop()),
                  const Spacer(),
                  if (_ids.length > 1)
                    Text(
                      'Ticket ${_page + 1} of ${_ids.length}',
                      style: T.body(15, color: C.darkMuted, weight: FontWeight.w600),
                    ),
                ],
              ),
            ),
            Expanded(
              child: PageView.builder(
                controller: _pages,
                itemCount: _ids.length,
                onPageChanged: (i) => setState(() => _page = i),
                itemBuilder: (_, i) => _TicketPage(ticketId: _ids[i]),
              ),
            ),
            if (_ids.length > 1)
              Padding(
                padding: const EdgeInsets.only(bottom: 8),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    for (var i = 0; i < _ids.length; i++)
                      AnimatedContainer(
                        duration: const Duration(milliseconds: 150),
                        margin: const EdgeInsets.symmetric(horizontal: 4),
                        width: i == _page ? 22 : 8,
                        height: 8,
                        decoration: BoxDecoration(color: i == _page ? C.gold : C.darkLine, borderRadius: BorderRadius.circular(4)),
                      ),
                  ],
                ),
              ),
            Padding(
              padding: const EdgeInsets.only(bottom: 14, top: 6),
              child: Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  const Icon(Icons.light_mode_outlined, color: C.darkMuted, size: 18),
                  const SizedBox(width: 8),
                  Text('Brightness raised for scanning', style: T.body(15, color: C.darkMuted)),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

/// One ticket: status, QR, holder name and the "Send to a friend" tools.
class _TicketPage extends StatefulWidget {
  final int ticketId;
  const _TicketPage({required this.ticketId});

  @override
  State<_TicketPage> createState() => _TicketPageState();
}

class _TicketPageState extends State<_TicketPage> with AutomaticKeepAliveClientMixin {
  final _view = GlobalKey<AsyncViewState<Ticket>>();

  @override
  bool get wantKeepAlive => true;

  Future<Ticket> _load() async => Ticket.fromJson(await api.get('/tickets/${widget.ticketId}'));

  @override
  Widget build(BuildContext context) {
    super.build(context);
    return Theme(
      data: Theme.of(context).copyWith(progressIndicatorTheme: const ProgressIndicatorThemeData(color: C.gold)),
      child: AsyncView<Ticket>(
        key: _view,
        load: _load,
        builder: (context, t, reload) {
          final e = t.event;
          final statusText = t.isCheckedIn
              ? 'Checked in${t.checkedInAt != null ? ' · ${Fmt.time(t.checkedInAt!)}' : ''}'
              : t.status == 'confirmed'
              ? 'Valid · not checked in'
              : t.status[0].toUpperCase() + t.status.substring(1);
          return ListView(
            padding: const EdgeInsets.fromLTRB(24, 8, 24, 16),
            children: [
              Center(
                child: Container(
                  padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
                  decoration: BoxDecoration(color: C.dark2, borderRadius: BorderRadius.circular(99)),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      CircleAvatar(radius: 5, backgroundColor: t.isCheckedIn ? const Color(0xFF5DBB8F) : C.gold),
                      const SizedBox(width: 8),
                      Text(
                        statusText,
                        style: T.body(15, color: C.bg, weight: FontWeight.w700),
                      ),
                    ],
                  ),
                ),
              ),
              const SizedBox(height: 22),
              Text(
                '${t.typeName.toUpperCase()} · ADMIT ONE',
                textAlign: TextAlign.center,
                style: T.eyebrow(color: C.gold),
              ),
              const SizedBox(height: 6),
              Text(
                e.title,
                textAlign: TextAlign.center,
                style: T.display(30, color: C.bg),
              ),
              const SizedBox(height: 4),
              Text(
                '${Fmt.shortDate(e.start)} · ${Fmt.time(e.start)} · ${e.place}',
                textAlign: TextAlign.center,
                style: T.body(15, color: C.darkMuted),
              ),
              const SizedBox(height: 22),
              ClipRRect(
                borderRadius: BorderRadius.circular(24),
                child: Container(
                  color: C.surface,
                  child: Column(
                    children: [
                      const TibebStrip(height: 10),
                      Padding(
                        padding: const EdgeInsets.fromLTRB(28, 24, 28, 22),
                        child: Column(
                          children: [
                            if (t.qrImage != null)
                              AspectRatio(
                                aspectRatio: 1,
                                child: Opacity(
                                  opacity: t.isUsable ? 1 : 0.25,
                                  child: Image.memory(
                                    base64Decode(t.qrImage!.split(',').last),
                                    fit: BoxFit.contain,
                                    filterQuality: FilterQuality.none,
                                  ),
                                ),
                              )
                            else
                              const AspectRatio(
                                aspectRatio: 1,
                                child: Center(child: Icon(Icons.qr_code_2, size: 120, color: C.line)),
                              ),
                            const SizedBox(height: 14),
                            Text(t.holderName ?? '', style: T.body(20, weight: FontWeight.w700)),
                            Text(
                              t.code,
                              style: T.mono(14, color: C.muted, weight: FontWeight.w500, spacing: 0.5),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
              ),
              if (t.receivedFrom != null) ...[
                const SizedBox(height: 14),
                Text(
                  '${t.receivedFrom} sent you this ticket.',
                  textAlign: TextAlign.center,
                  style: T.body(15, color: C.gold, weight: FontWeight.w600),
                ),
              ],
              if (t.pendingTransfer != null) ...[const SizedBox(height: 16), _pendingBox(t, reload)],
              const SizedBox(height: 18),
              Row(
                children: [
                  Expanded(
                    child: OutlinedButton(
                      style: OutlinedButton.styleFrom(
                        foregroundColor: C.bg,
                        side: const BorderSide(color: C.darkLine, width: 1.5),
                      ),
                      onPressed: () => Navigator.of(context).push(MaterialPageRoute(builder: (_) => EventDetailScreen(eventId: e.id))),
                      child: const Text('Event details'),
                    ),
                  ),
                  if (t.canTransfer && t.pendingTransfer == null) ...[
                    const SizedBox(width: 10),
                    Expanded(
                      child: OutlinedButton.icon(
                        style: OutlinedButton.styleFrom(
                          foregroundColor: C.gold,
                          side: const BorderSide(color: C.darkLine, width: 1.5),
                        ),
                        icon: const Icon(Icons.card_giftcard, size: 18),
                        label: const Text('Send to a friend'),
                        onPressed: () async {
                          final sent = await showModalBottomSheet<bool>(
                            context: context,
                            isScrollControlled: true,
                            backgroundColor: C.bg,
                            shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(24))),
                            builder: (_) => _TransferSheet(ticket: t),
                          );
                          if (sent == true) reload();
                        },
                      ),
                    ),
                  ],
                ],
              ),
            ],
          );
        },
      ),
    );
  }

  /// "Waiting for your friend to claim it" with an undo button.
  Widget _pendingBox(Ticket t, Future<void> Function() reload) {
    final p = t.pendingTransfer!;
    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: C.dark2,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: C.darkLine),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            'Sent to ${p['to_name'] ?? p['to_email']}',
            style: T.body(16, color: C.bg, weight: FontWeight.w700),
          ),
          const SizedBox(height: 4),
          Text("We emailed ${p['to_email']} a link to claim it. Until they do, this QR still works for you.", style: T.body(14, color: C.darkMuted)),
          const SizedBox(height: 10),
          TextButton(
            style: TextButton.styleFrom(foregroundColor: C.gold, padding: EdgeInsets.zero),
            onPressed: () async {
              try {
                await api.delete('/tickets/${t.id}/transfer');
                await reload();
                if (mounted) toast(context, 'Transfer cancelled. The ticket is yours again.');
              } catch (e) {
                if (mounted) toast(context, e);
              }
            },
            child: const Text('Cancel transfer'),
          ),
        ],
      ),
    );
  }
}

/// Bottom sheet: send this ticket to a friend by email. If the friend already
/// has an attendee account the ticket moves instantly; otherwise they get an
/// email with a claim link. Either way a new QR code is issued, so the old one
/// stops working (no double entry).
class _TransferSheet extends StatefulWidget {
  final Ticket ticket;
  const _TransferSheet({required this.ticket});

  @override
  State<_TransferSheet> createState() => _TransferSheetState();
}

class _TransferSheetState extends State<_TransferSheet> {
  final _email = TextEditingController();
  final _name = TextEditingController();
  String? _emailError;

  @override
  void dispose() {
    _email.dispose();
    _name.dispose();
    super.dispose();
  }

  Future<void> _send() async {
    setState(() => _emailError = null);
    try {
      final res = await api.post('/tickets/${widget.ticket.id}/transfer', {'email': _email.text.trim(), 'name': _name.text.trim()});
      if (!mounted) return;
      Navigator.of(context).pop(true);
      toast(
        context,
        res['status'] == 'claimed'
            ? 'Sent! The ticket is now in ${res['to_name']}\'s account.'
            : 'Sent! We emailed ${res['to_email']} a link to claim it.',
      );
    } on ApiException catch (e) {
      final field = e.fieldErrors['email'];
      if (field != null) {
        setState(() => _emailError = field);
      } else {
        rethrow;
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: EdgeInsets.fromLTRB(24, 20, 24, 20 + MediaQuery.of(context).viewInsets.bottom),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Center(
            child: Container(
              width: 40,
              height: 4,
              decoration: BoxDecoration(color: C.line, borderRadius: BorderRadius.circular(2)),
            ),
          ),
          const SizedBox(height: 18),
          Text('Send to a friend', style: T.display(28)),
          const SizedBox(height: 6),
          Text(
            "Your friend gets their own QR code for ${widget.ticket.event.title}. Once they have it, this ticket leaves your account. They can't pass it on again.",
            style: T.body(15, color: C.muted),
          ),
          const SizedBox(height: 18),
          TextField(
            controller: _email,
            keyboardType: TextInputType.emailAddress,
            decoration: InputDecoration(labelText: "Friend's email", errorText: _emailError),
          ),
          const SizedBox(height: 12),
          TextField(
            controller: _name,
            decoration: const InputDecoration(labelText: "Friend's name (optional)"),
          ),
          const SizedBox(height: 20),
          BusyButton(label: 'Send ticket', icon: Icons.send, onPressed: _send),
        ],
      ),
    );
  }
}
